import * as M from './data.js';import * as P from './planning.js';import {recipes} from './catalogue.js';
const {U,D}=M,$=id=>document.getElementById(id),say=s=>$('output').textContent+=new Date().toISOString()+' '+s+'\n',assert=(v,s)=>{if(!v)throw Error(s);say('PASS '+s);},get=async(c,h,t,id)=>(await D.getDocFromServer(M.entryRef(c,h,t,id))).data(),deny=async(label,fn)=>{try{await fn();throw Error('Se permitió '+label);}catch(e){if(e.code!=='permission-denied')throw e;say('PASS '+label+' rechazado por servidor');}};
$('prepare').onclick=async()=>{if(!['127.0.0.1','localhost'].includes(location.hostname)){say('Preparación de interfaz disponible solo en la prueba local.');return;}$('prepare').disabled=true;try{const c=M.context();await c.auth.authStateReady();if(c.auth.currentUser)throw Error('Ya hay una sesión en este origen local; no se cambiará.');await U.setPersistence(c.auth,U.browserSessionPersistence);await U.createUserWithEmailAndPassword(c.auth,'ui-'+M.id()+'@example.invalid',M.id()+'Aa1!');const h=await M.createHome(c,'Hogar ficticio de cantidades','Prueba local');for(const [name,qty,unit] of [['Garbanzos cocidos',800,'g'],['Tomates',4,'ud'],['Aceite de oliva',40,'ml'],['Sal',4,'g'],['Filete de Pollo',2,'ud']])await M.addLot(c,h,{name,qty,unit,place:'Nevera',date:'',dateType:''});const shopId=M.id();await M.commit(c,h,[{type:'shop',id:shopId,before:null,after:{name:'Tomates',qty:500,unit:'g',status:'open',lotId:'',createdAt:D.Timestamp.now()}}],{kind:'shopping'});const before=await get(c,h,'shop',shopId);await M.commit(c,h,[{type:'shop',id:shopId,before,after:{...before,status:'bought'}}],{kind:'shopping'});say('Hogar de interfaz preparado '+h+'. Abre la aplicación local. Cuenta distinta de la titular.');}catch(e){say('Preparación detenida: '+e.message);$('prepare').disabled=false;}};
$('run').onclick=async()=>{$('run').disabled=true;const run=M.id(),contexts=[],day=M.today();say('Ejecución '+run);try{const account=async n=>{const c=M.context('cantidades-'+n+'-'+run);contexts.push(c);await U.setPersistence(c.auth,U.inMemoryPersistence);await U.createUserWithEmailAndPassword(c.auth,n+'-'+run+'@example.invalid',M.id()+'Aa1!');return c;},a=await account('a'),h=await M.createHome(a,'Hogar ficticio cantidades '+run,'A'),token=await M.invitation(a,h),b=await account('b');await M.join(b,token,'B');
const r=recipes.find(r=>r.name==='Garbanzos con tomate'),ids=[];for(const [name,qty,unit] of [['Garbanzos cocidos',800,'g'],['Tomates',4,'ud'],['Aceite de oliva',40,'ml'],['Sal',4,'g']]){const id=M.id();ids.push(id);await M.addLot(a,h,{name,qty,unit,place:'Nevera',date:'',dateType:''},{lotId:id});}const read=async()=>Promise.all(ids.map(async id=>({id,...await get(a,h,'lot',id)}))),initial=await read(),tomId=ids[1],i=P.requirements(r,2,initial,day).find(i=>i.name==='Tomates'),choice=P.confirmPortion(i,initial,day,{[tomId]:2});assert(i.state==='pending'&&choice.unmeasured,'4 tomates en ud: pendientes, sin gramos inventados');try{P.purchase(r,2,initial,day);throw Error('Compra permitida sin revisar');}catch(e){assert(/primero/.test(e.message),'Tomates pendientes bloquean generación de compra');}
const plan=P.consumption(r,2,initial,day,{tomates:choice}),changes=plan.changes.map(({used,...x})=>x),group=M.id();let lastB=null;const stop=M.watch(b,h,s=>lastB=s,e=>say('Error observación B '+e.code));
assert((await M.commit(a,h,changes,{kind:'cook',group})).state==='applied','Cocinado confirmado descuenta 2 unidades del lote original');assert((await M.commit(a,h,changes,{kind:'cook',group})).state==='duplicate','Reintento de cocinado no duplica descuento');assert((await get(b,h,'lot',tomId)).qty===2,'Miembro B lee saldo 2 del servidor');for(let n=0;n<20&&!lastB?.lots.some(l=>l.id===tomId&&l.qty===2);n++)await new Promise(resolve=>setTimeout(resolve,100));assert(lastB?.lots.some(l=>l.id===tomId&&l.qty===2),'Actualización recibida por observador del segundo miembro');
const receipts=await D.getDocs(D.query(D.collection(a.db,`homes/${h}/receipts`),D.where('group','==',group))),records=receipts.docs.map(d=>({id:d.id,data:d.data()}));assert((await M.undo(a,h,records)).state==='applied','Corrección restaura tomates y demás ingredientes');assert((await M.undo(a,h,records)).state==='duplicate','Repetir corrección no suma existencias dos veces');assert((await get(b,h,'lot',tomId)).qty===4,'Miembro B ve cuatro tomates tras corrección');
const fresh=await read(),ingredient=P.requirements(r,2,fresh,day).find(i=>i.name==='Tomates'),ca=P.confirmPortion(ingredient,fresh,day,{[tomId]:3}),cb=P.confirmPortion(ingredient,fresh,day,{[tomId]:2}),pa=P.consumption(r,2,fresh,day,{tomates:ca}),pb=P.consumption(r,2,fresh,day,{tomates:cb}),ga=M.id(),gb=M.id(),results=await Promise.all([M.commit(a,h,pa.changes.map(({used,...x})=>x),{kind:'cook',group:ga}),M.commit(b,h,pb.changes.map(({used,...x})=>x),{kind:'cook',group:gb})]);assert(results.filter(x=>x.state==='applied').length===1&&results.filter(x=>x.state==='review').length===1,'Dos miembros cocinan: una operación se aplica y otra solicita revisión');const current=await get(b,h,'lot',tomId);assert(current.qty===(results[0].state==='applied'?1:2),'Saldo coincide con una sola operación, sin pérdida de cambios');
const after=await read();try{P.consumption(r,2,after,day,{tomates:ca});throw Error('Elección antigua válida');}catch(e){assert(/cambiado/.test(e.message),'Elección previa invalidada cuando cambia el lote');}try{P.confirmPortion({...ingredient},after,day,{[tomId]:5});throw Error('Saldo excedido');}catch(e){assert(/supera/.test(e.message),'Cantidad superior al saldo se bloquea');}await deny('Descuento negativo',()=>M.commit(a,h,[{type:'lot',id:tomId,before:current,after:{...current,qty:-1}}],{kind:'cook'}));assert((await get(b,h,'lot',tomId)).qty===current.qty,'Rechazo deja saldo intacto');
const winner=results[0].state==='applied'?a:b,winnerGroup=results[0].state==='applied'?ga:gb,wr=await D.getDocs(D.query(D.collection(winner.db,`homes/${h}/receipts`),D.where('group','==',winnerGroup))),winnerRecords=wr.docs.map(d=>({id:d.id,data:d.data()}));await M.commit(a,h,[{type:'lot',id:tomId,before:current,after:{...current,qty:current.qty+1}}],{kind:'edit'});assert((await M.undo(winner,h,winnerRecords)).state==='review','Corrección se detiene si otro miembro cambia el lote');
const si=M.id(),created={name:'Tomates',qty:500,unit:'g',status:'open',lotId:'',createdAt:D.Timestamp.now()};await M.commit(a,h,[{type:'shop',id:si,before:null,after:created}],{kind:'shopping'});let shopping=await get(a,h,'shop',si);await M.commit(a,h,[{type:'shop',id:si,before:shopping,after:{...shopping,status:'bought'}}],{kind:'shopping'});shopping=await get(a,h,'shop',si);const purchased=M.id(),ig=M.id(),actual={name:'Tomates pera ficticios',qty:4,unit:'ud',place:'Despensa',date:'2026-12-31',dateType:'Consumo preferente'};const wrong=M.id();await deny('Compra y lote con nombres distintos',()=>M.commit(a,h,[{type:'lot',id:wrong,before:null,after:M.newLot(actual,si)},{type:'shop',id:si,before:shopping,after:{...shopping,status:'incorporated',lotId:wrong}}],{kind:'incorporate'}));assert((await M.incorporate(a,h,si,shopping,actual,{group:ig,lotId:purchased})).state==='applied','Compra prevista 500 g se incorpora como 4 unidades realmente adquiridas');assert((await M.incorporate(a,h,si,shopping,actual,{group:ig,lotId:purchased})).state==='duplicate','Incorporación repetida crea un único lote');const incorporated=await get(b,h,'shop',si),received=await get(b,h,'lot',purchased);assert(incorporated.name===actual.name&&received.name===actual.name&&received.place===actual.place&&received.date===actual.date&&received.dateType===actual.dateType,'Nombre real, ubicación y fecha con tipo conservados en incorporación vinculada');assert(incorporated.status==='incorporated'&&incorporated.qty===4&&incorporated.unit==='ud'&&received.qty===4&&received.unit==='ud'&&incorporated.lotId===purchased,'Compra y lote coinciden atómicamente en cantidad real');
for(const [name,qty,unit,reference] of [['Tomates',0.5,'kg',500],['Aceite de oliva',0.75,'l',750]]){const id=M.id();await M.addLot(a,h,{name,qty,unit,place:'Despensa',date:'',dateType:''},{lotId:id});const value=await get(b,h,'lot',id);assert(value.unit===unit&&P.available([{id,...value}],name,unit==='kg'?'g':'ml',day)===reference,'Servidor conserva '+qty+' '+unit+' y comparación exacta '+reference);}
const outsider=await account('c');await deny('Lectura de tomates por cuenta sin pertenencia',()=>D.getDocFromServer(M.entryRef(outsider,h,'lot',tomId)));await deny('Información sanitaria',()=>D.updateDoc(M.homeRef(a,h),{allergies:['ficticia']}));stop();say('COMPLETADO SIN FALLOS. Hogar ficticio '+h);}catch(e){say('FALLO '+(e.code||'')+' '+e.message);}finally{for(const c of contexts)await U.signOut(c.auth).catch(()=>{});$('run').disabled=false;}};
